import{_ as o,C as a,o as n,c as i,a2 as t,E as s}from"./chunks/framework.BSaF8iZ6.js";const m=JSON.parse('{"title":"Reviews & Ratings","description":"","frontmatter":{},"headers":[],"relativePath":"moderation/rating-management.md","filePath":"moderation/rating-management.md","lastUpdated":1789411447000}'),l={name:"moderation/rating-management.md"};function g(d,e,h,p,c,v){const r=a("ImagePopup");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="reviews-ratings" tabindex="-1">Reviews &amp; Ratings <a class="header-anchor" href="#reviews-ratings" aria-label="Permalink to &quot;Reviews &amp; Ratings&quot;">​</a></h1><div class="page-roles"><span class="role role--customer">Customer</span><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>Customers can review a seller and the products they sell. Every new review waits for the admin to approve it before it counts towards a rating.</p><h2 id="seller-reviews" tabindex="-1">Seller reviews <a class="header-anchor" href="#seller-reviews" aria-label="Permalink to &quot;Seller reviews&quot;">​</a></h2><ul><li><strong>Who can write one:</strong> signed-in customers who have ordered from the seller. Each customer can review a seller once.</li><li><strong>Where:</strong> the <strong>Reviews</strong> tab of the seller&#39;s shop page. See <a href="./../storefront/seller-shop-page#review-a-seller">Seller Shop Page</a>.</li><li><strong>Where approved reviews count:</strong> the seller&#39;s star rating on their shop page and on their products, the featured sellers, and the <strong>Customer Feedback</strong> part of the seller&#39;s <a href="./../sellers/seller-account-health">Account Health</a>, which uses approved reviews from the last 90 days.</li></ul><h2 id="product-reviews" tabindex="-1">Product reviews <a class="header-anchor" href="#product-reviews" aria-label="Permalink to &quot;Product reviews&quot;">​</a></h2><p>Product reviews follow the store&#39;s own review settings in <strong>Configure &gt;&gt; Catalog &gt;&gt; Products</strong>: <strong>Allow Customer Review</strong> and <strong>Allow Guest Review</strong>. Customers don&#39;t need to have bought the product. A review of a product a seller created is linked to that seller.</p><h2 id="approve-reviews" tabindex="-1">Approve reviews <a class="header-anchor" href="#approve-reviews" aria-label="Permalink to &quot;Approve reviews&quot;">​</a></h2><h3 id="seller-reviews-1" tabindex="-1">Seller reviews <a class="header-anchor" href="#seller-reviews-1" aria-label="Permalink to &quot;Seller reviews&quot;">​</a></h3><ol><li>Go to <strong>Marketplace &gt;&gt; Sellers &gt;&gt; Seller Reviews</strong>.</li><li>Tick the reviews.</li><li>Click <strong>Select Action</strong>, point to <strong>Update Status</strong> and click <strong>Approved</strong>, <strong>Disapproved</strong> or <strong>Pending</strong>.</li></ol>',10)),s(r,{src:"/images/rating-management/admin-seller-reviews.png",alt:"Seller reviews waiting for approval in the admin panel"}),e[1]||(e[1]=t('<p>Each row shows the customer, the status, the seller and their business name, the rating, the date, and the review&#39;s title and comment. Click the delete icon to remove a review, or tick several and use <strong>Select Action &gt;&gt; Delete</strong>.</p><h3 id="product-reviews-1" tabindex="-1">Product reviews <a class="header-anchor" href="#product-reviews-1" aria-label="Permalink to &quot;Product reviews&quot;">​</a></h3><ol><li>Go to <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Product Reviews</strong>.</li><li>Click the view icon on a review. <strong>Review Details</strong> opens with the rating, title, comment and any photos.</li><li>Choose the <strong>Status</strong>: <strong>Approved</strong>, <strong>Disapproved</strong> or <strong>Pending</strong>.</li><li>Save.</li></ol>',3)),s(r,{src:"/images/rating-management/admin-product-reviews.png",alt:"Product reviews of seller products in the admin panel"}),e[2]||(e[2]=t('<p>To change several reviews at once, tick them and use <strong>Select Action &gt;&gt; Update Status</strong>. Click the delete icon to remove a review.</p><p>This list shows reviews of products sellers created. Reviews of your own products are managed in <strong>Customers &gt;&gt; Reviews</strong>.</p><h2 id="what-sellers-see" tabindex="-1">What sellers see <a class="header-anchor" href="#what-sellers-see" aria-label="Permalink to &quot;What sellers see&quot;">​</a></h2><ul><li><strong>Performance &gt;&gt; Seller Reviews</strong> lists the reviews of your shop, with each review&#39;s status.</li><li><strong>Performance &gt;&gt; Product Reviews</strong> lists the reviews of the products you created.</li></ul>',4)),s(r,{src:"/images/rating-management/seller-reviews.png",alt:"The seller's Seller Reviews page"}),e[3]||(e[3]=t('<p>Both lists are read-only. Sellers can&#39;t approve, reply to or delete reviews. Customer email addresses are masked when the store doesn&#39;t let sellers see customer details.</p><p>No emails are sent when a review is written or approved.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li>Admins need <strong>Marketplace &gt;&gt; Sellers &gt;&gt; Seller Reviews</strong> or <strong>Marketplace &gt;&gt; Catalog &gt;&gt; Product Reviews</strong>, with <strong>Edit</strong> and <strong>Delete</strong>.</li><li>Team members need <strong>Performance</strong>, with <strong>Seller Reviews</strong> and <strong>Product Reviews</strong>.</li></ul>',4))])}const u=o(l,[["render",g]]);export{m as __pageData,u as default};
